/**
 * seed-cases.ts
 * -------------
 * Reads cases-seed.json (generated by parse-cases.py) and upserts all
 * 246 mock cases into MongoDB, linked to the first active admin user.
 *
 * Pre-requisites:
 *   1. MONGO_URI set in .env
 *   2. At least one admin user exists (run `npm run seed:admin` first)
 *   3. cases-seed.json is present next to this file
 *      (or generated fresh: python3 parse-cases.py cases.docx --output src/scripts/cases-seed.json)
 *
 * Station images (stationImageUrl) live in cases-seed.json and are upserted with
 * each case. If you regenerate the JSON from the docx, run this first:
 *   npm run restore:station-images
 *
 * Usage:
 *   npm run seed:cases                            # upsert, leave isPublished as-is
 *   npm run seed:cases -- --publish               # upsert + publish all cases
 *   npm run seed:cases -- --wipe                  # drop all cases first, then insert
 *   npm run seed:cases -- --file /path/to/file.json
 *
 * Re-running is always safe — cases are matched on stationNumber and upserted.
 */

import mongoose from 'mongoose';
import fs from 'fs';
import path from 'path';
import dotenv from 'dotenv';

dotenv.config();

// ─────────────────────────────────────────────────────────────────────────────
// CLI flags
// ─────────────────────────────────────────────────────────────────────────────

const args         = process.argv.slice(2);
const fileFlag     = args.indexOf('--file');
const shouldPublish = args.includes('--publish');
const shouldWipe   = args.includes('--wipe');

const DEFAULT_JSON = path.resolve(__dirname, 'cases-seed.json');
const jsonPath     = fileFlag !== -1 && args[fileFlag + 1]
  ? path.resolve(args[fileFlag + 1])
  : DEFAULT_JSON;

// ─────────────────────────────────────────────────────────────────────────────
// Guards
// ─────────────────────────────────────────────────────────────────────────────

if (!process.env.MONGO_URI) {
  console.error('❌  MONGO_URI is not set in your .env file');
  process.exit(1);
}

if (!fs.existsSync(jsonPath)) {
  console.error(`❌  Seed file not found: ${jsonPath}`);
  console.error('    Generate it first:');
  console.error('    python3 src/scripts/parse-cases.py <cases.docx> --output src/scripts/cases-seed.json');
  process.exit(1);
}

// ─────────────────────────────────────────────────────────────────────────────
// Seed
// ─────────────────────────────────────────────────────────────────────────────

const seed = async () => {
  console.log('🔌  Connecting to MongoDB...');
  await mongoose.connect(process.env.MONGO_URI!);
  console.log('✅  Connected\n');

  // Dynamic imports after connection so Mongoose registers models correctly
  const { MockCase } = await import('../modules/cases/model/cases.model');
  const { User }     = await import('../modules/auth/model/auth.model');

  // ── Resolve admin ──────────────────────────────────────────────────────────
  const admin = await User.findOne({ role: 'admin', isActive: true }).lean();
  if (!admin) {
    console.error('❌  No active admin found. Run `npm run seed:admin` first.');
    await mongoose.disconnect();
    process.exit(1);
  }
  console.log(`👤  Admin: ${admin.fullName} (${admin.email})\n`);

  // ── Optional wipe ──────────────────────────────────────────────────────────
  if (shouldWipe) {
    const count = await MockCase.countDocuments();
    await MockCase.deleteMany({});
    console.log(`🗑️   Wiped ${count} existing cases\n`);
  }

  // ── Load JSON ──────────────────────────────────────────────────────────────
  console.log(`📂  Loading ${path.basename(jsonPath)}...`);
  const cases: Record<string, unknown>[] = JSON.parse(
    fs.readFileSync(jsonPath, 'utf-8'),
  );
  console.log(`    ${cases.length} cases found\n`);

  // ── Get existing station numbers so we can count new vs updated accurately ─
  const existingNums = new Set(
    (await MockCase.find({}, 'stationNumber').lean()).map((c) => c.stationNumber),
  );

  // ── Upsert loop ────────────────────────────────────────────────────────────
  let inserted = 0, updated = 0, failed = 0;
  const failures: Array<{ station: number; error: string }> = [];

  for (const rawCase of cases) {
    const stationNumber = rawCase.stationNumber as number;

    const doc: Record<string, unknown> = {
      ...rawCase,
      createdBy:   admin._id,
      isPublished: shouldPublish ? true : (rawCase.isPublished ?? false),
    };

    try {
      await MockCase.findOneAndUpdate(
        { stationNumber },
        { $set: doc },
        { upsert: true, returnDocument: 'after', runValidators: true },
      );

      if (existingNums.has(stationNumber)) {
        updated++;
      } else {
        inserted++;
        existingNums.add(stationNumber); // prevent double-counting on retry
      }
    } catch (err) {
      failed++;
      const msg = err instanceof Error ? err.message : String(err);
      failures.push({ station: stationNumber, error: msg });
    }

    // Live progress line
    process.stdout.write(
      `\r  ⏳  ${String(stationNumber).padStart(3)} / ${cases.length}` +
      `   ✅ ${inserted} new   🔄 ${updated} updated   ❌ ${failed} failed`,
    );
  }

  // ── Results ────────────────────────────────────────────────────────────────
  console.log('\n');
  console.log('─────────────────────────────────────────');
  console.log(`✅  Inserted : ${inserted}`);
  console.log(`🔄  Updated  : ${updated}`);
  console.log(`❌  Failed   : ${failed}`);

  if (failures.length) {
    console.log('\n⚠️  Failed stations:');
    failures.forEach(({ station, error }) => {
      console.log(`  Station ${String(station).padStart(3)}: ${error.slice(0, 140)}`);
    });
  }

  // ── Final DB state ─────────────────────────────────────────────────────────
  const [total, publishedCount] = await Promise.all([
    MockCase.countDocuments(),
    MockCase.countDocuments({ isPublished: true }),
  ]);

  console.log(`\n📊  DB now contains ${total} cases (${publishedCount} published)`);

  if (!shouldPublish && publishedCount === 0) {
    console.log('\n💡  All cases are currently drafts. To publish them:');
    console.log('    npm run seed:cases -- --publish');
  }

  await mongoose.disconnect();
  console.log('\n✔   Done');
};

seed().catch((err) => {
  console.error('\n❌  Seeder crashed:', err);
  mongoose.disconnect().finally(() => process.exit(1));
});